def comps(g, bg):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; cells=[]
                seen.add((i,j))
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            if da or db:
                                x,y=a+da,b+db
                                if 0<=x<R and 0<=y<C and (x,y) not in seen and g[x][y]==col:
                                    seen.add((x,y)); st.append((x,y))
                out.append((col,len(cells)))
    from collections import Counter
    return Counter(out)

def norm(cells):
    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))

