def shapes_abs(g, bg):
    R,Cn=len(g),len(g[0]); seen=set(); out=[]
    for i in range(R):
        for j in range(Cn):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; cs=set(); seen.add((i,j))
                while st:
                    a,b=st.pop(); cs.add((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            if da or db:
                                x,y=a+da,b+db
                                if 0<=x<R and 0<=y<Cn and (x,y) not in seen and g[x][y]==col:
                                    seen.add((x,y)); st.append((x,y))
                out.append((col,sorted(cs)))
    return out

